#include "emulator.hpp"
#include "multi_warp_emulator.hpp"
#include <fstream>
#include <iostream>
#include <iterator>
static std::vector<uint32_t> read_words(const std::string& p) { std::ifstream f(p,std::ios::binary); if(!f) throw std::runtime_error("cannot open program: "+p); std::vector<unsigned char>b((std::istreambuf_iterator<char>(f)),{}); if(b.size()%4) throw std::runtime_error("program size is not a multiple of four"); std::vector<uint32_t>w; for(size_t i=0;i<b.size();i+=4) w.push_back(uint32_t(b[i])|(uint32_t(b[i+1])<<8)|(uint32_t(b[i+2])<<16)|(uint32_t(b[i+3])<<24)); return w; }
int main(int argc,char**argv){ try { if(argc<2){std::cerr<<"usage: simt-emulator PROGRAM [--warps 1..4] [--runs N] [--initial-epoch N] [--memory FILE] [--dump FILE] [--trace FILE]\n";return 2;} std::string mem,dump="build/state.txt",trace; unsigned warps=1,runs=1,initial_epoch=0; for(int i=2;i<argc;i++){std::string a=argv[i]; if((a=="--memory"||a=="--dump"||a=="--trace"||a=="--warps"||a=="--runs"||a=="--initial-epoch")&&i+1<argc){auto v=std::string(argv[++i]);if(a=="--memory")mem=v;else if(a=="--dump")dump=v;else if(a=="--trace")trace=v;else if(a=="--warps")warps=unsigned(std::stoul(v));else if(a=="--runs")runs=unsigned(std::stoul(v));else initial_epoch=unsigned(std::stoul(v));}else throw std::runtime_error("bad argument: "+a);} if(runs==0)throw std::runtime_error("run count must be positive");if(initial_epoch>63)throw std::runtime_error("initial epoch must fit in six bits");auto words=read_words(argv[1]); if(warps>1){if(!mem.empty())throw std::runtime_error("multi-warp memory execution is not implemented");simt::MultiWarpEmulator e(warps);e.load_program(words);for(unsigned epoch=0;epoch<initial_epoch;++epoch)e.relaunch();bool ok=true;for(unsigned run=0;run<runs&&ok;++run){if(run)e.relaunch();ok=e.run();}if(!trace.empty())e.dump_trace(trace);std::cout<<"cycles="<<e.cycles()<<" issues="<<e.issues()<<" commits="<<e.commits()<<" warps="<<warps<<" runs="<<runs<<" fault="<<e.faulted()<<" fault_pc="<<e.fault_pc()<<"\n";return ok?0:1;} if(runs!=1||initial_epoch!=0)throw std::runtime_error("lifecycle options require multi-warp mode");simt::Emulator e; e.load_program(words); if(!mem.empty())e.load_memory_text(mem); auto r=e.run(); e.dump(dump);if(!trace.empty())e.dump_trace(trace); std::cout<<"steps="<<r.steps<<" exited="<<r.exited<<" fault="<<int(r.fault)<<" fault_pc="<<r.fault_pc<<"\n"; return r.fault==simt::Fault::None&&r.exited?0:1; }catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 2;} }
